import{at as e,n as t,rt as n,xt as r}from"./chunks/framework.DIOWbp6D.js";var i=JSON.parse(`{"title":"Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"strategy/index.md","filePath":"strategy/index.md"}`),a={name:`strategy/index.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="strategy" tabindex="-1">Strategy <a class="header-anchor" href="#strategy" aria-label="Permalink to “Strategy”">​</a></h1><p>Where Handl is going, what it is for, and the values that shape every decision in the ecosystem.</p><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to “Vision”">​</a></h2><p>A programming ecosystem where the mathematics is the substrate. Computation as arrows, not functions; programs, laws, coherence, and effects as data you can inspect, rewrite, and execute. Language infrastructure that tools, libraries, and products can build on without inheriting a hidden runtime.</p><h2 id="mission" tabindex="-1">Mission <a class="header-anchor" href="#mission" aria-label="Permalink to “Mission”">​</a></h2><p>Build <strong>handl-lang</strong>: a modular language infrastructure around a closed arrow calculus with globular higher-categorical structure.</p><ul><li>The <strong>kernel</strong> defines the computational foundation: arrow calculus, IR, value representation, and language schema.</li><li><strong>Engines</strong> interpret and transform the shared representation: compilation, execution, rewriting, and language processing.</li><li><strong>Libraries</strong> (<code>lib-*</code>) provide runtime-agnostic abstractions in separate repositories.</li><li><strong>Kits</strong> (<code>kit-*</code>) assemble libraries, engines, and components into ready-to-use environments.</li><li><strong>Tools</strong> (SDK generators, CLI/WebIDL bridges) connect Handl to external systems.</li><li><strong>Hosts</strong> (CLI, LSP) and <strong>extensions</strong> (VS Code, Neovim) expose the platform to users and editors.</li></ul><p>One principle holds the stack together: composition over application, and inspectable structure over hidden closures.</p><p>See the <a href="/docs/paradigm/">paradigm</a> for what the calculus buys you and the <a href="/docs/ecosystem/">ecosystem</a> for how the repos fit together.</p><h2 id="values" tabindex="-1">Values <a class="header-anchor" href="#values" aria-label="Permalink to “Values”">​</a></h2><ul><li><strong>Composition over application.</strong> Arrows compose; nothing needs to be unwrapped to be understood.</li><li><strong>Inspectable structure over hidden closures.</strong> If a tool cannot see it, it is not part of the model.</li><li><strong>The mathematics is the spec.</strong> Laws, coherence, and graded effects are data, not folklore in a paper.</li><li><strong>Runtime independence.</strong> Libraries do not know which engine runs them; engines do not know which library called them.</li><li><strong>Honest work in progress.</strong> Incomplete, unreviewed, and subject to change is stated plainly, not hidden behind confidence.</li></ul><h2 id="where-it-leads" tabindex="-1">Where it leads <a class="header-anchor" href="#where-it-leads" aria-label="Permalink to “Where it leads”">​</a></h2><p>The same foundation that describes a language also describes its tools, its libraries, and its products. Research projects like <a href="https://github.com/handl-lang/mlopt" target="_blank" rel="noreferrer">mlopt</a> are early proof that the substrate carries real workloads, not just notation.</p>`,13)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};